const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link = (url, text) => `<a href="${esc(url)}">${esc(text)}</a>`;
const evidence = (file, text = file) => link('../evidence/' + file, text);
const table = (heads, rows, cls='') => `<div class="table-wrap"><table class="${cls}"><thead><tr>${heads.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const badge = s => `<span class="badge ${s.toLowerCase().split(' ')[0]}">${esc(s)}</span>`;

